	    LOGGER.info("assigning TimeSeries as " + assignment.toString() );

	    Anomaly parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( TimeSeries.class, assignment.getTimeSeriesId());

	    // ------------------------------------------
